// src/components/dashboard/Dashboard.tsx
import { useState, useEffect, useCallback } from 'react';
import { supabase } from '../../db/supabase';
import styles from './Dashboard.module.css';

interface Proyecto { id: string; nombre: string; cliente: string | null; }
interface Orden {
  id: string; ot: string | null; estado: string | null;
  responsable: string | null; rubro: string | null;
  prioridad: string | null; proyecto_id: string | null; updated_at: string | null;
}

const ESTADO_CFG: Record<string, { color: string; bg: string; text: string }> = {
  'Pendiente':  { color: '#EF4444', bg: '#FEF2F2', text: '#991B1B' },
  'En proceso': { color: '#2462C9', bg: '#EFF4FF', text: '#1E40AF' },
  'Cerrada':    { color: '#22C55E', bg: '#F0FDF4', text: '#166534' },
  'No aplica':  { color: '#9CA3AF', bg: '#F8FAFC', text: '#4B5563' },
};
const ESTADOS = Object.keys(ESTADO_CFG);

function fmt(n: number) { return n.toLocaleString('es-PY'); }
function trunc(s: string, max: number) { return s.length > max ? s.slice(0, max) + '…' : s; }

function DonutChart({ data, total }: { data: { label: string; value: number; color: string }[]; total: number }) {
  const R = 46, STROKE = 18, r = R - STROKE / 2;
  const circ = 2 * Math.PI * r;
  const pctCerr = total > 0 ? Math.round(((data.find(d => d.label === 'Cerrada')?.value || 0) / total) * 100) : 0;
  let offset = 0;
  const arcs = data.filter(d => d.value > 0).map((d, i) => {
    const pct = d.value / total;
    const dash = pct * circ, gap = circ - dash;
    const dOff = -(offset * circ - circ / 4);
    offset += pct;
    return <circle key={i} cx="56" cy="56" r={r} fill="none" stroke={d.color}
      strokeWidth={STROKE} strokeDasharray={`${dash.toFixed(2)} ${gap.toFixed(2)}`}
      strokeDashoffset={dOff} strokeLinecap="butt"/>;
  });
  return (
    <svg width="112" height="112" viewBox="0 0 112 112" style={{ flexShrink: 0 }}>
      <circle cx="56" cy="56" r={r} fill="none" stroke="var(--bg-subtle)" strokeWidth={STROKE}/>
      {arcs}
      <text x="56" y="52" textAnchor="middle" dominantBaseline="middle" fontSize="15"
        fontWeight="700" fill="var(--text-primary)" fontFamily="var(--font-sans)">{pctCerr}%</text>
      <text x="56" y="66" textAnchor="middle" dominantBaseline="middle" fontSize="9"
        fill="var(--text-tertiary)" fontFamily="var(--font-sans)">cerradas</text>
    </svg>
  );
}

interface DashboardProps { onBack?: () => void; }

export default function Dashboard({ onBack }: DashboardProps) {
  const [proyectos,  setProyectos]  = useState<Proyecto[]>([]);
  const [ordenes,    setOrdenes]    = useState<Orden[]>([]);
  const [loading,    setLoading]    = useState(true);
  const [error,      setError]      = useState<string | null>(null);
  const [filtro,     setFiltro]     = useState<string>('todos');
  const [lastUpdate, setLastUpdate] = useState<Date | null>(null);

  const fetchAll = useCallback(async () => {
    setLoading(true);
    setError(null);
    try {
      const [{ data: proys, error: e1 }, { data: ords, error: e2 }] = await Promise.all([
        supabase.from('proyectos').select('id, nombre, cliente').is('deleted_at', null).order('nombre'),
        supabase.from('ordenes').select('id, ot, estado, responsable, rubro, prioridad, proyecto_id, updated_at').order('updated_at', { ascending: false }),
      ]);
      if (e1) throw new Error(e1.message);
      if (e2) throw new Error(e2.message);
      setProyectos(proys ?? []);
      setOrdenes(ords ?? []);
      setLastUpdate(new Date());
    } catch (e: unknown) {
      setError(e instanceof Error ? e.message : 'Error desconocido');
    } finally {
      setLoading(false);
    }
  }, []);

  // ← la línea que faltaba
  useEffect(() => { fetchAll(); }, [fetchAll]);

  const filtered = filtro === 'todos' ? ordenes : ordenes.filter(o => o.proyecto_id === filtro);
  const total    = filtered.length;
  const counts: Record<string, number> = {};
  ESTADOS.forEach(e => { counts[e] = filtered.filter(o => o.estado === e).length; });
  const pctCerr = total > 0 ? Math.round((counts['Cerrada'] / total) * 100) : 0;

  const respMap: Record<string, number> = {};
  filtered.forEach(o => { if (o.responsable) respMap[o.responsable] = (respMap[o.responsable] || 0) + 1; });
  const byResp  = Object.entries(respMap).sort((a, b) => b[1] - a[1]).slice(0, 8);
  const maxResp = byResp[0]?.[1] || 1;

  const rubroMap: Record<string, number> = {};
  filtered.forEach(o => { if (o.rubro) rubroMap[o.rubro] = (rubroMap[o.rubro] || 0) + 1; });
  const byRubro  = Object.entries(rubroMap).sort((a, b) => b[1] - a[1]).slice(0, 8);
  const maxRubro = byRubro[0]?.[1] || 1;

  const now   = Date.now();
  const weeks = Array.from({ length: 8 }, (_, i) => {
    const weekStart = new Date(now - (7 - i) * 7 * 86400000);
    const weekEnd   = new Date(now - (6 - i) * 7 * 86400000);
    const vals: Record<string, number> = {};
    ESTADOS.forEach(e => { vals[e] = 0; });
    filtered.forEach(o => {
      if (!o.updated_at || !o.estado) return;
      const d = new Date(o.updated_at);
      if (d >= weekStart && d < weekEnd && vals[o.estado] !== undefined) vals[o.estado]++;
    });
    return { label: weekStart.toLocaleDateString('es-PY', { day: '2-digit', month: '2-digit' }), vals };
  });
  const maxWeek  = Math.max(1, ...weeks.map(w => Object.values(w.vals).reduce((a, b) => a + b, 0)));
  const donutData = ESTADOS.map(e => ({ label: e, value: counts[e], color: ESTADO_CFG[e].color })).filter(d => d.value > 0);
  const recentOTs = filtered.slice(0, 10);

  return (
    <div className={styles.wrap}>
      <div className={styles.topBar}>
        <div className={styles.topBarLeft}>
          <div className={styles.logoBlock}>
            <div className={styles.logoIcon}>
              <svg viewBox="0 0 16 16" fill="none" stroke="#fff" strokeWidth="1.5">
                <rect x="1" y="1" width="14" height="14" rx="2"/>
                <line x1="4" y1="6" x2="12" y2="6" strokeLinecap="round"/>
                <line x1="4" y1="9" x2="9" y2="9" strokeLinecap="round"/>
                <circle cx="12" cy="11" r="2"/>
              </svg>
            </div>
            <span className={styles.logoName}>Plan-OTs</span>
          </div>
          <div className={styles.divider}/>
          <span className={styles.pageTitle}>Dashboard Ejecutivo</span>
        </div>
        <div className={styles.topBarRight}>
          {lastUpdate && (
            <span className={styles.lastUpdate}>
              Actualizado {lastUpdate.toLocaleTimeString('es-PY', { hour: '2-digit', minute: '2-digit' })}
            </span>
          )}
          {onBack && <button className={styles.btnBack} onClick={onBack}>← Volver</button>}
          <button className={styles.btnRefresh} onClick={fetchAll} disabled={loading}>
            <span className={loading ? styles.spin : undefined}>↻</span>
            {loading ? 'Cargando…' : 'Actualizar'}
          </button>
        </div>
      </div>

      <div className={styles.content}>
        {error && <div className={styles.errorBanner}>⚠ {error}</div>}

        {loading ? (
          <div className={styles.loadingState}>
            <div className={styles.loadingSpinner}/>
            <span>Cargando datos…</span>
          </div>
        ) : !error && (
          <>
            <div className={styles.projSection}>
              <span className={styles.projLabel}>Proyecto</span>
              <button className={`${styles.pill} ${filtro === 'todos' ? styles.pillActive : ''}`} onClick={() => setFiltro('todos')}>
                Todos ({ordenes.length})
              </button>
              {proyectos.map(p => (
                <button key={p.id} className={`${styles.pill} ${filtro === p.id ? styles.pillActive : ''}`} onClick={() => setFiltro(p.id)}>
                  {trunc(p.nombre, 24)}
                </button>
              ))}
            </div>

            <div className={styles.kpiRow}>
              {[
                { label: 'Total OTs',   value: fmt(total),                   sub: `${proyectos.length} proyecto${proyectos.length !== 1 ? 's' : ''}`, color: '#2462C9', progress: false },
                { label: 'Avance global', value: `${pctCerr}%`,              sub: '',                                                                  color: '#22C55E', progress: true  },
                { label: 'En proceso',  value: fmt(counts['En proceso']),     sub: `${total > 0 ? Math.round((counts['En proceso'] / total) * 100) : 0}% del total`, color: '#2462C9', progress: false },
                { label: 'Pendientes',  value: fmt(counts['Pendiente']),      sub: `${total > 0 ? Math.round((counts['Pendiente'] / total) * 100) : 0}% del total`,  color: '#EF4444', progress: false },
              ].map(k => (
                <div key={k.label} className={styles.kpiCard}>
                  <div className={styles.kpiAccent} style={{ background: k.color }}/>
                  <div className={styles.kpiLabel}>{k.label}</div>
                  <div className={styles.kpiValue}>{k.value}</div>
                  {k.progress ? (
                    <div className={styles.kpiProgress}>
                      <div className={styles.kpiProgressFill} style={{ width: `${pctCerr}%` }}/>
                    </div>
                  ) : k.sub ? <div className={styles.kpiSub}>{k.sub}</div> : null}
                </div>
              ))}
            </div>

            <div className={styles.chartsRow}>
              <div className={styles.card}>
                <div className={styles.cardTitle}>Distribución por estado <span className={styles.cardTitleSub}>{fmt(total)} OTs</span></div>
                {total > 0 ? (
                  <div className={styles.donutWrap}>
                    <DonutChart data={donutData} total={total}/>
                    <div className={styles.donutLegend}>
                      {ESTADOS.map(e => (
                        <div key={e} className={styles.donutLegItem}>
                          <div className={styles.donutLegLeft}>
                            <div className={styles.donutLegSq} style={{ background: ESTADO_CFG[e].color }}/>
                            {e}
                          </div>
                          <span className={styles.donutLegVal}>{fmt(counts[e])}</span>
                        </div>
                      ))}
                    </div>
                  </div>
                ) : <div style={{ textAlign: 'center', color: 'var(--text-tertiary)', fontSize: 'var(--text-xs)', padding: '24px 0' }}>Sin OTs</div>}
              </div>

              <div className={styles.card}>
                <div className={styles.cardTitle}>Por estado</div>
                <div className={styles.stateGrid}>
                  {ESTADOS.map(e => {
                    const cfg = ESTADO_CFG[e];
                    return (
                      <div key={e} className={styles.stateCard} style={{ background: cfg.bg }}>
                        <div className={styles.stateN} style={{ color: cfg.color }}>{fmt(counts[e])}</div>
                        <div className={styles.stateL} style={{ color: cfg.text }}>{e}</div>
                      </div>
                    );
                  })}
                </div>
              </div>
            </div>

            <div className={styles.chartsRow}>
              <div className={styles.card}>
                <div className={styles.cardTitle}>Por responsable <span className={styles.cardTitleSub}>top {Math.min(byResp.length, 8)}</span></div>
                <div className={styles.barContainer}>
                  {byResp.length > 0 ? byResp.map(([name, val]) => (
                    <div key={name} className={styles.barRow}>
                      <div className={styles.barName}>{trunc(name, 16)}</div>
                      <div className={styles.barTrack}>
                        <div className={styles.barFill} style={{ width: `${Math.round((val / maxResp) * 100)}%`, background: '#2462C9' }}/>
                      </div>
                      <div className={styles.barVal}>{val}</div>
                    </div>
                  )) : <div className={styles.barEmpty}>Sin datos</div>}
                </div>
              </div>

              <div className={styles.card}>
                <div className={styles.cardTitle}>Por rubro <span className={styles.cardTitleSub}>top {Math.min(byRubro.length, 8)}</span></div>
                <div className={styles.barContainer}>
                  {byRubro.length > 0 ? byRubro.map(([name, val]) => (
                    <div key={name} className={styles.barRow}>
                      <div className={styles.barName}>{trunc(name, 16)}</div>
                      <div className={styles.barTrack}>
                        <div className={styles.barFill} style={{ width: `${Math.round((val / maxRubro) * 100)}%`, background: '#7C3AED' }}/>
                      </div>
                      <div className={styles.barVal}>{val}</div>
                    </div>
                  )) : <div className={styles.barEmpty}>Sin datos</div>}
                </div>
              </div>
            </div>

            <div className={styles.card}>
              <div className={styles.cardTitle}>Actividad — últimas 8 semanas <span className={styles.cardTitleSub}>por fecha de actualización</span></div>
              <div className={styles.timelineWrap}>
                {weeks.map((w, i) => {
                  const tot      = Object.values(w.vals).reduce((a, b) => a + b, 0);
                  const widthPct = tot > 0 ? Math.max((tot / maxWeek) * 100, 2) : 0;
                  return (
                    <div key={i} className={styles.tlRow}>
                      <div className={styles.tlWeek}>{w.label}</div>
                      <div className={styles.tlBars} style={{ width: `${widthPct}%`, minWidth: tot > 0 ? 4 : 0 }}>
                        {ESTADOS.map(e => {
                          const v   = w.vals[e] || 0;
                          const pct = tot > 0 ? (v / tot) * 100 : 0;
                          return v > 0 ? (
                            <div key={e} className={styles.tlSeg}
                              style={{ height: 12, width: `${pct}%`, minWidth: 3, background: ESTADO_CFG[e].color }}
                              title={`${e}: ${v}`}/>
                          ) : null;
                        })}
                      </div>
                      <div className={styles.tlCount}>{tot > 0 ? tot : ''}</div>
                    </div>
                  );
                })}
                <div className={styles.tlLegend}>
                  {ESTADOS.map(e => (
                    <div key={e} className={styles.tlLegItem}>
                      <div className={styles.tlLegDot} style={{ background: ESTADO_CFG[e].color }}/>
                      {e}
                    </div>
                  ))}
                </div>
              </div>
            </div>

            {recentOTs.length > 0 && (
              <div className={styles.recentCard}>
                <div className={styles.cardTitle}>Últimas OTs modificadas <span className={styles.cardTitleSub}>máx. 10</span></div>
                <table className={styles.otTable}>
                  <thead>
                    <tr><th>Código</th><th>Estado</th><th>Responsable</th><th>Rubro</th><th>Prioridad</th><th>Actualizado</th></tr>
                  </thead>
                  <tbody>
                    {recentOTs.map(o => {
                      const cfg   = ESTADO_CFG[o.estado || ''] || ESTADO_CFG['No aplica'];
                      const fecha = o.updated_at
                        ? new Date(o.updated_at).toLocaleDateString('es-PY', { day: '2-digit', month: '2-digit', year: '2-digit' })
                        : '—';
                      return (
                        <tr key={o.id}>
                          <td><span className={styles.otCode}>{o.ot || '—'}</span></td>
                          <td>
                            <span className={styles.estadoBadge} style={{ background: cfg.bg, color: cfg.text }}>
                              <span className={styles.estadoDot} style={{ background: cfg.color }}/>
                              {o.estado || '—'}
                            </span>
                          </td>
                          <td>{trunc(o.responsable || '—', 20)}</td>
                          <td>{trunc(o.rubro || '—', 20)}</td>
                          <td>{o.prioridad || '—'}</td>
                          <td style={{ fontFamily: 'var(--font-mono)', fontSize: 10 }}>{fecha}</td>
                        </tr>
                      );
                    })}
                  </tbody>
                </table>
              </div>
            )}
          </>
        )}
      </div>
    </div>
  );
}

import React, { useEffect, useState } from 'react';
import styles from './ModalDetalleOT.module.css';
import {
  emojiRubro,
  colorEstado,
  diasAbierto,
  formatearGuaranies,
} from '../../utils/calculos';
import {
  cargarFotosDeOrden,
  type FotoSubida,
  type CategoriaFoto,
} from '../../services/fotosService';
import { usePuedeVerCostos } from '../../hooks/usePuedeVerCostos';

// ─────────────────────────────────────────────────────────────────── Types ──

type EstadoOT    = 'Pendiente' | 'En proceso' | 'Cerrada' | 'No aplica';
type PrioridadOT = 'Alta' | 'Media' | 'Baja';

interface OrdenTrabajo {
  id: string;
  proyecto_id: string;
  ot: string;
  estado: EstadoOT;
  prioridad: PrioridadOT;
  responsable: string;
  rubro: string;
  ubicacion: string;
  comentarios?: string;
  pos_x?: number;
  pos_y?: number;
  campos?: Record<string, unknown>;
  created_at?: string;
  updated_at?: string;
  fecha_ingreso?: string;
  obra?: string;
  unidad_amenities?: string;
  descripcion?: string;
  en_garantia?: boolean;
  asiste_facility?: boolean;
  costo?: number;
  nivel_riesgo?: 'Bajo' | 'Medio' | 'Alto' | 'Extremo' | null;
  rubro_secundario?: string[];
  contratistas?: string[];
  fecha_inicio_trabajos?: string;
  porcentaje_avance?: number;
  fecha_fin_trabajos?: string;
  reincidencia?: boolean;
  potencialmente_conflictivo?: boolean;
  acta_conformidad?: 'Pendiente' | 'enviada' | 'firmada' | 'no aplica';
  informe_relevamiento?: 'Pendiente' | 'enviada' | 'no aplica';
  informe_avance?: 'Pendiente' | 'enviada' | 'no aplica';
  informe_cierre?: 'Pendiente' | 'enviada' | 'no aplica';
}

interface Props {
  orden: OrdenTrabajo | null;
  proyectoId: string;
  onClose: () => void;
  onGuardado: () => void;
  onEditar?: () => void;
}

// ─────────────────────────────────────────────────────────────────── Helpers ──

const COLOR_RIESGO: Record<string, string> = {
  Bajo:    '#16A34A',
  Medio:   '#D97706',
  Alto:    '#EA580C',
  Extremo: '#DC2626',
};

/**
 * Formatea fecha ISO a DD/MM/YYYY.
 * Fuerza parseo local (T00:00:00) para evitar el desfase UTC→Paraguay (UTC-4).
 */
const formatFecha = (iso?: string): string => {
  if (!iso) return '—';
  // Si es solo fecha (YYYY-MM-DD), agregar T00:00:00 para parsear en hora local
  const normalized = iso.length === 10 ? iso + 'T00:00:00' : iso;
  const d = new Date(normalized);
  if (isNaN(d.getTime())) return '—';
  return d.toLocaleDateString('es-PY', {
    day: '2-digit', month: '2-digit', year: 'numeric',
  });
};

/**
 * Muestra fecha + hora si hay hora disponible.
 * Ejemplo: "14/05/2026 · 08:30"
 */
const FechaConHora: React.FC<{ fecha?: string; hora?: string }> = ({ fecha, hora }) => {
  if (!fecha) return <span className={styles.dash}>—</span>;
  return (
    <span>
      {formatFecha(fecha)}
      {hora && (
        <span style={{ color: 'var(--text-secondary)', marginLeft: 6, fontSize: '0.92em' }}>
          · {hora}
        </span>
      )}
    </span>
  );
};

const Dash: React.FC = () => <span className={styles.dash}>—</span>;

const SiNoChip: React.FC<{ valor?: boolean }> = ({ valor }) => (
  <span className={valor ? styles.chipSi : styles.chipNo}>
    {valor ? 'Sí' : 'No'}
  </span>
);

const DOC_LABEL: Record<string, string> = {
  'pendiente': 'Pendiente',
  'enviada':   'Enviada',
  'firmada':   'Firmada',
  'no aplica': 'N.A.',
};

const InformeChip: React.FC<{ valor?: string }> = ({ valor }) => {
  if (!valor) return <Dash />;
  const norm = valor.toLowerCase();
  const claseMap: Record<string, string> = {
    'pendiente': styles.docPendiente,
    'enviada':   styles.docEnviada,
    'firmada':   styles.docFirmada,
    'no aplica': styles.docNoAplica,
  };
  const cls = claseMap[norm] ?? styles.docNoAplica;
  return <span className={`${styles.docChip} ${cls}`}>{DOC_LABEL[norm] ?? valor}</span>;
};

const Campo: React.FC<{ label: string; children: React.ReactNode; full?: boolean }> = ({
  label, children, full,
}) => (
  <div className={`${styles.campo} ${full ? styles.campoFull : ''}`}>
    <div className={styles.campoLabel}>{label}</div>
    <div className={styles.campoValor}>{children}</div>
  </div>
);

const Seccion: React.FC<{ titulo: string; children: React.ReactNode }> = ({
  titulo, children,
}) => (
  <section className={styles.seccion}>
    <h3 className={styles.seccionTitulo}>{titulo}</h3>
    <div className={styles.grid}>{children}</div>
  </section>
);

type FotoConId = FotoSubida & { id: string };

// ─────────────────────────────────────────────────────────────────── Componente ──

export const ModalDetalleOT: React.FC<Props> = ({
  orden, onClose, onEditar,
}) => {
  const [fotos, setFotos] = useState<FotoConId[]>([]);
  const puedeVerCostos = usePuedeVerCostos(orden?.proyecto_id ?? null);

  useEffect(() => {
    if (!orden) return;
    cargarFotosDeOrden(orden.id)
      .then(setFotos)
      .catch(err => console.error('[ModalDetalleOT] fotos:', err));
  }, [orden?.id]);

  if (!orden) return null;

  const fotosPorCategoria = (cat: CategoriaFoto) =>
    fotos.filter(f => f.categoria === cat);

  const fotosAntes   = fotosPorCategoria('ANTES');
  const fotosDurante = fotosPorCategoria('DURANTE');
  const fotosDespues = fotosPorCategoria('DESPUES');
  const hayFotos = fotosAntes.length + fotosDurante.length + fotosDespues.length > 0;

  const dias = diasAbierto(
    orden.fecha_ingreso || orden.created_at,
    orden.estado === 'Cerrada' ? orden.fecha_fin_trabajos : undefined,
  );

  // Horas desde campos JSONB
  const horaInicio = orden.campos?.hora_inicio_trabajos as string | undefined;
  const horaFin    = orden.campos?.hora_fin_trabajos    as string | undefined;

  const handleOverlayClick = (e: React.MouseEvent) => {
    if (e.target === e.currentTarget) onClose();
  };

  const colorEst = colorEstado(orden.estado);

  return (
    <div className={styles.overlay} onClick={handleOverlayClick}>
      <div className={styles.modal}>

        {/* ─ Header ─ */}
        <header className={styles.header}>
          <div className={styles.headerLeft}>
            <span className={styles.rubroEmoji}>{emojiRubro(orden.rubro)}</span>
            <div className={styles.headerInfo}>
              <div className={styles.headerCodigo}>{orden.ot}</div>
              <div className={styles.headerObra}>
                {orden.obra || orden.ubicacion || 'Sin obra asignada'}
              </div>
            </div>
            <span
              className={styles.estadoBadge}
              style={{ background: colorEst, boxShadow: `0 0 0 3px ${colorEst}30` }}
            >
              {orden.estado}
            </span>
          </div>

          <div className={styles.headerActions}>
            {onEditar && (
              <button className={styles.btnEditar} onClick={onEditar} title="Editar OT">
                ✎ Editar
              </button>
            )}
            <button className={styles.btnCerrar} onClick={onClose} title="Cerrar">
              ✕
            </button>
          </div>
        </header>

        {/* ─ Body ─ */}
        <div className={styles.body}>

          {/* ────── Sección 1 – Identificación ────── */}
          <Seccion titulo="📋 Identificación">
            <Campo label="Código OT"><strong>{orden.ot}</strong></Campo>
            <Campo label="Fecha de ingreso">{formatFecha(orden.fecha_ingreso || orden.created_at)}</Campo>
            <Campo label="Días abierto">
              <strong>{dias}</strong> {dias === 1 ? 'día' : 'días'}
            </Campo>
            <Campo label="Obra">{orden.obra || <Dash />}</Campo>
            <Campo label="Unidad / Amenities">{orden.unidad_amenities || <Dash />}</Campo>
            <Campo label="Descripción" full>
              {orden.descripcion || orden.comentarios || <Dash />}
            </Campo>
          </Seccion>

          {/* ────── Sección 2 – Clasificación ────── */}
          <Seccion titulo="🔧 Clasificación">
            <Campo label="Estado">
              <span className={styles.estadoPill} style={{ background: colorEst }}>
                {orden.estado}
              </span>
            </Campo>
            <Campo label="Prioridad">
              <span className={`${styles.prioridadPill} ${styles[`prio${orden.prioridad}`]}`}>
                {orden.prioridad}
              </span>
            </Campo>
            <Campo label="Rubro principal">{orden.rubro || <Dash />}</Campo>
            <Campo label="Rubros secundarios">
              {orden.rubro_secundario && orden.rubro_secundario.length > 0
                ? <div className={styles.chipsRow}>
                    {orden.rubro_secundario.map(r => (
                      <span key={r} className={styles.chip}>{emojiRubro(r)} {r}</span>
                    ))}
                  </div>
                : <Dash />}
            </Campo>
            <Campo label="Nivel de riesgo">
              {orden.nivel_riesgo
                ? <strong style={{ color: COLOR_RIESGO[orden.nivel_riesgo] }}>
                    {orden.nivel_riesgo}
                  </strong>
                : <Dash />}
            </Campo>
            <Campo label="En Garantía"><SiNoChip valor={orden.en_garantia} /></Campo>
            <Campo label="Asiste Facility"><SiNoChip valor={orden.asiste_facility} /></Campo>
            <Campo label="Reincidencia"><SiNoChip valor={orden.reincidencia} /></Campo>
            <Campo label="Potenc. conflictivo"><SiNoChip valor={orden.potencialmente_conflictivo} /></Campo>
          </Seccion>

          {/* ────── Sección 3 – Ejecución ────── */}
          <Seccion titulo="🏗️ Ejecución">
            <Campo label="Responsable">{orden.responsable || <Dash />}</Campo>
            <Campo label="Contratistas">
              {orden.contratistas && orden.contratistas.length > 0
                ? <div className={styles.chipsRow}>
                    {orden.contratistas.map(c => (
                      <span key={c} className={styles.chip}>{c}</span>
                    ))}
                  </div>
                : <Dash />}
            </Campo>
            <Campo label="Fecha inicio">
              <FechaConHora fecha={orden.fecha_inicio_trabajos} hora={horaInicio} />
            </Campo>
            <Campo label="Fecha fin">
              <FechaConHora fecha={orden.fecha_fin_trabajos} hora={horaFin} />
            </Campo>
            <Campo label="% Avance" full>
              <div className={styles.avanceWrap}>
                <div className={styles.avanceBar}>
                  <div
                    className={styles.avanceFill}
                    style={{ width: `${Math.max(0, Math.min(100, orden.porcentaje_avance ?? 0))}%` }}
                  />
                </div>
                <span className={styles.avanceNum}>{orden.porcentaje_avance ?? 0}%</span>
              </div>
            </Campo>
            {puedeVerCostos && (
              <Campo label="Costo" full>
                <strong style={{ fontSize: 15 }}>
                  {orden.costo != null && orden.costo > 0
                    ? formatearGuaranies(orden.costo)
                    : <Dash />}
                </strong>
              </Campo>
            )}
            <Campo label="Comentarios" full>
              {orden.comentarios
                ? <p className={styles.parrafo}>{orden.comentarios}</p>
                : <Dash />}
            </Campo>
          </Seccion>

          {/* ────── Sección 4 – Documentos ────── */}
          <Seccion titulo="📄 Documentos">
            <Campo label="Acta de conformidad"><InformeChip valor={orden.acta_conformidad} /></Campo>
            <Campo label="Informe relevamiento"><InformeChip valor={orden.informe_relevamiento} /></Campo>
            <Campo label="Informe avance"><InformeChip valor={orden.informe_avance} /></Campo>
            <Campo label="Informe cierre"><InformeChip valor={orden.informe_cierre} /></Campo>
          </Seccion>

          {/* ────── Sección 5 – Fotos ────── */}
          {hayFotos && (
            <section className={styles.seccion}>
              <h3 className={styles.seccionTitulo}>📷 Fotos</h3>

              {fotosAntes.length > 0 && (
                <div className={styles.fotoGrupo}>
                  <div className={styles.fotoCategoria}>ANTES</div>
                  <div className={styles.fotosGrid}>
                    {fotosAntes.map(f => (
                      <a key={f.id} href={f.url} target="_blank" rel="noreferrer" className={styles.fotoThumb}>
                        <img src={f.url} alt={f.nombre} loading="lazy" />
                      </a>
                    ))}
                  </div>
                </div>
              )}

              {fotosDurante.length > 0 && (
                <div className={styles.fotoGrupo}>
                  <div className={styles.fotoCategoria}>DURANTE</div>
                  <div className={styles.fotosGrid}>
                    {fotosDurante.map(f => (
                      <a key={f.id} href={f.url} target="_blank" rel="noreferrer" className={styles.fotoThumb}>
                        <img src={f.url} alt={f.nombre} loading="lazy" />
                      </a>
                    ))}
                  </div>
                </div>
              )}

              {fotosDespues.length > 0 && (
                <div className={styles.fotoGrupo}>
                  <div className={styles.fotoCategoria}>DESPUÉS</div>
                  <div className={styles.fotosGrid}>
                    {fotosDespues.map(f => (
                      <a key={f.id} href={f.url} target="_blank" rel="noreferrer" className={styles.fotoThumb}>
                        <img src={f.url} alt={f.nombre} loading="lazy" />
                      </a>
                    ))}
                  </div>
                </div>
              )}
            </section>
          )}

        </div>
      </div>
    </div>
  );
};

// src/components/informes/InformePanel.tsx
import { useState, useRef, useEffect } from 'react'
import { useProyectosStore } from '../../stores/proyectosStore'
import { ESTADO_COLOR, ESTADO_LABEL, ESTADOS_ORDEN } from '../../constants/estados'
import type { EstadoOT } from '../../constants/estados'
import { getCamposDeProyecto } from '../../services/camposService'
import {
  generarInformeHTML,
  exportarCSV,
  descargarHTML,
} from '../../services/informeService'
import type { InformeConfig, FirmanteConfig } from '../../services/informeService'
import styles from './InformePanel.module.css'

interface Props { onClose: () => void }

const CATS_FOTOS = ['ANTES', 'DURANTE', 'DESPUÉS'] as const
type CatFoto = typeof CATS_FOTOS[number]

export default function InformePanel({ onClose }: Props) {
  const proyecto = useProyectosStore(s => s.proyectoActivo)

  const [filtroEstados, setFiltroEstados]     = useState<EstadoOT[]>([...ESTADOS_ORDEN])
  const [incluirFotos, setIncluirFotos]       = useState(false)
  const [categoriasFotos, setCategoriasFotos] = useState<CatFoto[]>([...CATS_FOTOS])
  const [granularidad, setGranularidad]       = useState<'dias' | 'semanas' | 'meses'>('semanas')
  const [campoAvanceId, setCampoAvanceId]     = useState('')
  const [periodoLabel, setPeriodoLabel]       = useState('')
  const [firmantes, setFirmantes]             = useState<FirmanteConfig[]>([
    { nombre: '', cargo: '' },
    { nombre: '', cargo: '' },
  ])
  const [logoB64, setLogoB64]                 = useState<string | undefined>()
  const [camposNumericos, setCamposNumericos] = useState<{ id: string; nombre: string }[]>([])
  const [generando, setGenerando]             = useState(false)
  const [htmlGenerado, setHtmlGenerado]       = useState<string | null>(null)

  const iframeRef    = useRef<HTMLIFrameElement>(null)
  const logoInputRef = useRef<HTMLInputElement>(null)

  useEffect(() => {
    if (!proyecto) return
    const saved = localStorage.getItem(`plan-ots-logo-${proyecto.id}`)
    if (saved) setLogoB64(saved)
    getCamposDeProyecto(proyecto.id).then(campos =>
      setCamposNumericos(
        campos
          .filter(c => c.tipo === 'numero' || c.tipo === 'decimal')
          .map(c => ({ id: c.id, nombre: c.nombre }))
      )
    )
  }, [proyecto?.id])

  if (!proyecto) return null
  const proj = proyecto

  function toggleEstado(e: EstadoOT) {
    setFiltroEstados(prev =>
      prev.includes(e) ? prev.filter(x => x !== e) : [...prev, e]
    )
  }

  function toggleCategoria(cat: CatFoto) {
    setCategoriasFotos(prev =>
      prev.includes(cat) ? prev.filter(c => c !== cat) : [...prev, cat]
    )
  }

  function handleLogo(e: React.ChangeEvent<HTMLInputElement>) {
    const file = e.target.files?.[0]
    if (!file) return
    const reader = new FileReader()
    reader.onload = ev => {
      const b64 = ev.target?.result as string
      setLogoB64(b64)
      localStorage.setItem(`plan-ots-logo-${proj.id}`, b64)
    }
    reader.readAsDataURL(file)
  }

  function actualizarFirmante(i: number, campo: keyof FirmanteConfig, valor: string) {
    setFirmantes(prev => {
      const next = [...prev]
      next[i] = { ...next[i], [campo]: valor }
      return next
    })
  }

  async function generar() {
    setGenerando(true)
    try {
      const config: InformeConfig = {
        proyectoId:            proj.id,
        proyectoNombre:        proj.nombre,
        proyectoCliente:       proj.cliente ?? '',
        periodoLabel:          periodoLabel || new Date().toLocaleDateString('es-PY', { month: 'long', year: 'numeric' }),
        logoB64,
        filtroEstados,
        incluirFotos,
        categoriasFotos:       incluirFotos ? categoriasFotos : [],
        campoAvanceId:         campoAvanceId || undefined,
        evolucionGranularidad: granularidad,
        firmantes:             firmantes.filter(f => f.nombre.trim()),
      }
      const html = await generarInformeHTML(config)
      setHtmlGenerado(html)
    } finally {
      setGenerando(false)
    }
  }

  function descargar() {
    if (!htmlGenerado) return
    const nombre = `informe-${proj.nombre.replace(/\s+/g, '-').toLowerCase()}-${new Date().toISOString().slice(0, 10)}.html`
    descargarHTML(htmlGenerado, nombre)
  }

  function imprimirPDF() {
    iframeRef.current?.contentWindow?.print()
  }

  return (
    <div className={styles.overlay}>
      <div className={styles.panel}>

        <div className={styles.header}>
          <h2 className={styles.titulo}>Generar informe — {proj.nombre}</h2>
          <button className={styles.btnCerrar} onClick={onClose}>✕</button>
        </div>

        <div className={styles.body}>

          {/* Config 2 columnas */}
          <div className={styles.config}>
            <div className={styles.configGrid}>

              <div className={styles.colLeft}>
                <div className={styles.seccion}>
                  <p className={styles.secLabel}>Logo de empresa</p>
                  <div className={styles.logoArea} onClick={() => logoInputRef.current?.click()}>
                    {logoB64
                      ? <img src={logoB64} className={styles.logoPreview} alt="Logo" />
                      : <span className={styles.logoPlaceholder}>Clic para subir PNG/JPG</span>
                    }
                  </div>
                  <input ref={logoInputRef} type="file" accept="image/*"
                    style={{ display: 'none' }} onChange={handleLogo} />
                  {logoB64 && (
                    <button className={styles.btnLink} onClick={() => {
                      setLogoB64(undefined)
                      localStorage.removeItem(`plan-ots-logo-${proj.id}`)
                    }}>Quitar logo</button>
                  )}
                </div>

                <div className={styles.seccion}>
                  <p className={styles.secLabel}>Estados a incluir</p>
                  <div className={styles.chipGroup}>
                    {ESTADOS_ORDEN.map(e => (
                      <button key={e}
                        className={`${styles.chip} ${filtroEstados.includes(e) ? styles.chipActivo : ''}`}
                        style={filtroEstados.includes(e) ? { borderColor: ESTADO_COLOR[e], color: ESTADO_COLOR[e] } : {}}
                        onClick={() => toggleEstado(e)}>
                        {ESTADO_LABEL[e]}
                      </button>
                    ))}
                  </div>
                </div>

                <div className={styles.seccion}>
                  <p className={styles.secLabel}>Fotos por OT</p>
                  <label className={styles.toggleRow}>
                    <input type="checkbox" checked={incluirFotos}
                      onChange={e => setIncluirFotos(e.target.checked)} />
                    Incluir fotos
                  </label>
                  {incluirFotos && (
                    <div className={styles.chipGroup}>
                      {CATS_FOTOS.map(cat => (
                        <button key={cat}
                          className={`${styles.chip} ${categoriasFotos.includes(cat) ? styles.chipActivo : ''}`}
                          onClick={() => toggleCategoria(cat)}>{cat}</button>
                      ))}
                    </div>
                  )}
                </div>
              </div>

              <div className={styles.colRight}>
                <div className={styles.seccion}>
                  <p className={styles.secLabel}>Período</p>
                  <input className={styles.input} placeholder="ej: enero – mayo 2026"
                    value={periodoLabel} onChange={e => setPeriodoLabel(e.target.value)} />
                </div>

                <div className={styles.seccion}>
                  <p className={styles.secLabel}>Línea temporal</p>
                  <div className={styles.radioGroup}>
                    {(['dias', 'semanas', 'meses'] as const).map(g => (
                      <label key={g} className={styles.radioLabel}>
                        <input type="radio" name="gran" value={g}
                          checked={granularidad === g} onChange={() => setGranularidad(g)} />
                        {g.charAt(0).toUpperCase() + g.slice(1)}
                      </label>
                    ))}
                  </div>
                </div>

                {camposNumericos.length > 0 && (
                  <div className={styles.seccion}>
                    <p className={styles.secLabel}>Campo % avance</p>
                    <select className={styles.input} value={campoAvanceId}
                      onChange={e => setCampoAvanceId(e.target.value)}>
                      <option value="">— Sin barra —</option>
                      {camposNumericos.map(c => (
                        <option key={c.id} value={c.id}>{c.nombre}</option>
                      ))}
                    </select>
                  </div>
                )}

                <div className={styles.seccion}>
                  <p className={styles.secLabel}>Firmantes</p>
                  {firmantes.map((f, i) => (
                    <div key={i} className={styles.firmanteRow}>
                      <input className={styles.input} placeholder="Nombre"
                        value={f.nombre} onChange={e => actualizarFirmante(i, 'nombre', e.target.value)} />
                      <input className={styles.input} placeholder="Cargo"
                        value={f.cargo} onChange={e => actualizarFirmante(i, 'cargo', e.target.value)} />
                      {firmantes.length > 1 && (
                        <button className={styles.btnLink}
                          onClick={() => setFirmantes(prev => prev.filter((_, idx) => idx !== i))}>✕</button>
                      )}
                    </div>
                  ))}
                  <button className={styles.btnLink}
                    onClick={() => setFirmantes(prev => [...prev, { nombre: '', cargo: '' }])}>
                    + Firmante
                  </button>
                </div>

                <div className={styles.acciones}>
                  <button className={styles.btnGenerar} onClick={generar}
                    disabled={generando || filtroEstados.length === 0}>
                    {generando ? 'Generando…' : '▶ Vista previa'}
                  </button>
                  <button className={styles.btnSecundario} onClick={() => exportarCSV(proj.id)}>
                    CSV
                  </button>
                </div>
              </div>

            </div>
          </div>

          {/* Preview */}
          <div className={styles.preview}>
            {htmlGenerado ? (
              <>
                <div className={styles.previewToolbar}>
                  <span className={styles.previewLabel}>Vista previa</span>
                  <button className={styles.btnSecundario} onClick={descargar}>Descargar HTML</button>
                  <button className={styles.btnGenerar} onClick={imprimirPDF}>Imprimir / PDF</button>
                </div>
                <p className={styles.avisoImpresion}>
                  Se abrirá el diálogo de impresión de Android. Para volver, usá el botón atrás.
                </p>
                <iframe ref={iframeRef} className={styles.iframe}
                  srcDoc={htmlGenerado} title="Vista previa del informe" />
              </>
            ) : (
              <div className={styles.previewEmpty}>
                <span>Configurá el informe<br />y presioná <strong>▶ Vista previa</strong></span>
              </div>
            )}
          </div>

        </div>
      </div>
    </div>
  )
}

