// src/components/informes/ModalInformeOT.tsx
//
// Modal fullscreen para previsualizar/exportar informes de OT. Soporta 5
// tipos: 'cierre' | 'ficha' | 'relevamiento' | 'avance' | 'acta'.
//
// Layout: panel izquierdo (datos read-only + observaciones editable + opciones),
// panel derecho (iframe srcdoc con el HTML generado).
//
// Carga inicial varía según tipo:
//   cierre       → comentario "En proceso → Cerrada" + fotos ANTES y DESPUÉS.
//   ficha        → orden.comentarios (sin fetch) + sin fotos.
//   relevamiento → comentario "Pendiente → En proceso" + fotos ANTES.
//   avance       → comentario "Pendiente → En proceso" + fotos ANTES + DURANTE.
//   acta         → sin texto editable + sin fotos.
//
// Estrategia de actualización del preview:
// - Tipeo en observaciones → parche directo del <p> dentro del DOM del iframe
//   (sin recargar). Cero parpadeo, latencia inmediata.
// - Cambio de opciones (incluirFotos), carga inicial, cambio de OT/tipo → regen
//   completa del HTML y reload del iframe via srcDoc.
//
// S33: FotoMin incluye descripcion_observacion (campo del EditorFoto).
//      Los tres mapeos de fotos ahora pasan ese campo al generador de informes.

import { useEffect, useRef, useState } from 'react';
import type { OrdenLocal } from '../../types/orden';
import {
  generarInformeCierre,
  generarInformeFichaVisita,
  generarInformeRelevamiento,
  generarInformeAvance,
  generarInformeActaConformidad,
} from '../../services/reportService';
import { fetchComentarioTransicion } from '../../services/comentariosService';
import { cargarFotosDeOrden } from '../../services/fotosService';
import { colorEstado } from '../../utils/calculos';
import styles from './ModalInformeOT.module.css';

export type TipoInforme = 'cierre' | 'ficha' | 'relevamiento' | 'avance' | 'acta';

interface Props {
  isOpen: boolean;
  onClose: () => void;
  orden: OrdenLocal;
  proyectoNombre: string;
  tipo: TipoInforme;
}

// S33: incluye descripcion_observacion para que aparezca en los informes
type FotoMin = {
  file_url: string;
  descripcion?: string | null;
  descripcion_observacion?: string | null;
};

interface TipoCfg {
  titulo: string;
  tituloDoc: string;
  fileSlug: string;
  labelTextarea: string | null;       // null => textarea oculto (caso 'acta')
  placeholderTextarea: string;
  necesitaFotosAntes: boolean;
  necesitaFotosDespues: boolean;
  necesitaFotosDurante: boolean;
}

const TIPO_CFG: Record<TipoInforme, TipoCfg> = {
  cierre: {
    titulo: 'Informe de Cierre',
    tituloDoc: 'Informe de Cierre de OT - BBC Constructora',
    fileSlug: 'Informe_Cierre',
    labelTextarea: 'Antecedentes y Diagnóstico *',
    placeholderTextarea: 'Ingresá los antecedentes y diagnóstico de la OT...',
    necesitaFotosAntes: true,
    necesitaFotosDespues: true,
    necesitaFotosDurante: false,
  },
  ficha: {
    titulo: 'Ficha de Visita Técnica',
    tituloDoc: 'Ficha de Visita - BBC Constructora',
    fileSlug: 'Ficha_Visita',
    labelTextarea: 'Descripción del Trabajo',
    placeholderTextarea: 'Describí brevemente el trabajo a realizar...',
    necesitaFotosAntes: false,
    necesitaFotosDespues: false,
    necesitaFotosDurante: false,
  },
  relevamiento: {
    titulo: 'Informe de Relevamiento',
    tituloDoc: 'Informe de Relevamiento - BBC Constructora',
    fileSlug: 'Informe_Relevamiento',
    labelTextarea: 'Diagnóstico Inicial',
    placeholderTextarea: 'Detallá el diagnóstico técnico inicial...',
    necesitaFotosAntes: true,
    necesitaFotosDespues: false,
    necesitaFotosDurante: false,
  },
  avance: {
    titulo: 'Informe de Avance',
    tituloDoc: 'Informe de Avance - BBC Constructora',
    fileSlug: 'Informe_Avance',
    labelTextarea: 'Estado Actual del Trabajo',
    placeholderTextarea: 'Describí el progreso actual de los trabajos...',
    necesitaFotosAntes: true,
    necesitaFotosDespues: false,
    necesitaFotosDurante: true,
  },
  acta: {
    titulo: 'Acta de Conformidad',
    tituloDoc: 'Acta de Conformidad - BBC Constructora',
    fileSlug: 'Acta_Conformidad',
    labelTextarea: null,
    placeholderTextarea: '',
    necesitaFotosAntes: false,
    necesitaFotosDespues: false,
    necesitaFotosDurante: false,
  },
};

function fechaCorta(fecha: string | null | undefined): string {
  if (!fecha) return '—';
  const d = new Date(fecha + 'T00:00:00');
  if (isNaN(d.getTime())) return '—';
  const dd = String(d.getDate()).padStart(2, '0');
  const mm = String(d.getMonth() + 1).padStart(2, '0');
  return `${dd}/${mm}/${d.getFullYear()}`;
}

const DEBOUNCE_MS = 150;
const MAX_OBSERVACIONES = 2000;

export function ModalInformeOT({ isOpen, onClose, orden, proyectoNombre, tipo }: Props) {
  const cfg = TIPO_CFG[tipo];
  const necesitaFotos =
    cfg.necesitaFotosAntes || cfg.necesitaFotosDespues || cfg.necesitaFotosDurante;
  const muestraTextarea = cfg.labelTextarea !== null;

  const [observaciones, setObservaciones] = useState('');
  const [cargandoComentario, setCargandoComentario] = useState(true);
  const [htmlPreview, setHtmlPreview] = useState('');
  const [generandoPreview, setGenerandoPreview] = useState(false);
  const [incluirFotos, setIncluirFotos] = useState(true);
  const [fotosAntes, setFotosAntes] = useState<FotoMin[]>([]);
  const [fotosDespues, setFotosDespues] = useState<FotoMin[]>([]);
  const [fotosDurante, setFotosDurante] = useState<FotoMin[]>([]);

  const firstRenderRef = useRef(true);
  const prevIncluirFotosRef = useRef(incluirFotos);
  const iframeRef = useRef<HTMLIFrameElement>(null);

  // Reset de flags al cambiar de OT o tipo
  useEffect(() => {
    firstRenderRef.current = true;
    setHtmlPreview('');
    setObservaciones('');
    setFotosAntes([]);
    setFotosDespues([]);
    setFotosDurante([]);
  }, [orden.id, tipo]);

  const construirHtml = (textoActual: string): string => {
    const fa  = incluirFotos ? fotosAntes   : [];
    const fd  = incluirFotos ? fotosDespues : [];
    const fdu = incluirFotos ? fotosDurante : [];
    switch (tipo) {
      case 'cierre':
        return generarInformeCierre(orden, proyectoNombre, textoActual, fa, fd);
      case 'ficha':
        return generarInformeFichaVisita(orden, textoActual);
      case 'relevamiento':
        return generarInformeRelevamiento(orden, textoActual, fa);
      case 'avance':
        return generarInformeAvance(orden, textoActual, fa, fdu);
      case 'acta':
        return generarInformeActaConformidad(orden);
    }
  };

  // Carga inicial: comentario + fotos
  useEffect(() => {
    if (!isOpen) return;
    let cancelado = false;
    setCargandoComentario(true);

    let promComentario: Promise<string>;
    switch (tipo) {
      case 'cierre':
        promComentario = fetchComentarioTransicion(orden.id, 'En proceso', 'Cerrada');
        break;
      case 'relevamiento':
      case 'avance':
        promComentario = fetchComentarioTransicion(orden.id, 'Pendiente', 'En proceso');
        break;
      case 'ficha':
        promComentario = Promise.resolve(orden.comentarios ?? '');
        break;
      case 'acta':
      default:
        promComentario = Promise.resolve('');
        break;
    }

    const promFotos = necesitaFotos
      ? cargarFotosDeOrden(orden.id)
      : Promise.resolve([] as Awaited<ReturnType<typeof cargarFotosDeOrden>>);

    Promise.all([promComentario, promFotos])
      .then(([com, fotos]) => {
        if (cancelado) return;
        setObservaciones(com);

        // S33: mapeo incluye descripcion_observacion además de descripcion
        if (cfg.necesitaFotosAntes) {
          setFotosAntes(
            fotos
              .filter(f => f.categoria === 'ANTES')
              .map(f => ({
                file_url: f.url,
                descripcion: f.descripcion ?? null,
                descripcion_observacion: (f as any).descripcion_observacion ?? null,
              })),
          );
        }
        if (cfg.necesitaFotosDespues) {
          setFotosDespues(
            fotos
              .filter(f => f.categoria === 'DESPUES')
              .map(f => ({
                file_url: f.url,
                descripcion: f.descripcion ?? null,
                descripcion_observacion: (f as any).descripcion_observacion ?? null,
              })),
          );
        }
        if (cfg.necesitaFotosDurante) {
          setFotosDurante(
            fotos
              .filter(f => f.categoria === 'DURANTE')
              .map(f => ({
                file_url: f.url,
                descripcion: f.descripcion ?? null,
                descripcion_observacion: (f as any).descripcion_observacion ?? null,
              })),
          );
        }
        setCargandoComentario(false);
      })
      .catch(err => {
        console.error('[ModalInformeOT] carga inicial:', err);
        if (!cancelado) setCargandoComentario(false);
      });
    return () => {
      cancelado = true;
    };
  }, [isOpen, orden.id, tipo, necesitaFotos, cfg.necesitaFotosAntes, cfg.necesitaFotosDespues, cfg.necesitaFotosDurante, orden.comentarios]);

  // Regeneración del preview ante cambios que requieren rebuild completo
  useEffect(() => {
    if (!isOpen || cargandoComentario) return;
    const incluirFotosCambio = prevIncluirFotosRef.current !== incluirFotos;
    prevIncluirFotosRef.current = incluirFotos;
    const delay = firstRenderRef.current || incluirFotosCambio ? 0 : DEBOUNCE_MS;
    firstRenderRef.current = false;
    setGenerandoPreview(true);
    const t = window.setTimeout(() => {
      setHtmlPreview(construirHtml(observaciones));
      setGenerandoPreview(false);
    }, delay);
    return () => {
      window.clearTimeout(t);
    };
    // `observaciones` fuera de deps a propósito — se parchea el DOM directamente
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [
    isOpen,
    cargandoComentario,
    incluirFotos,
    fotosAntes,
    fotosDespues,
    fotosDurante,
    orden,
    proyectoNombre,
    tipo,
  ]);

  if (!isOpen) return null;

  const handleActualizarAhora = () => {
    if (cargandoComentario) return;
    setGenerandoPreview(true);
    setHtmlPreview(construirHtml(observaciones));
    setGenerandoPreview(false);
  };

  const handleExportarHTML = () => {
    if (cargandoComentario) return;
    const html = construirHtml(observaciones);
    const blob = new Blob([html], { type: 'text/html;charset=utf-8' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    const fecha = new Date().toISOString().slice(0, 10);
    a.href = url;
    a.download = `${cfg.fileSlug}_OT${orden.ot}_${fecha}.html`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
  };

  const handleExportarPDF = () => {
    if (cargandoComentario) return;
    const html = construirHtml(observaciones);
    const w = window.open('', '_blank');
    if (!w) return;
    w.document.open();
    w.document.write(html);
    w.document.close();
    w.onload = () => {
      w.document.title = cfg.tituloDoc;
      setTimeout(() => w.print(), 250);
    };
  };

  // ── Render ───────────────────────────────────────────────────────────────
  return (
    <div className={styles.backdrop} onClick={onClose}>
      <div className={styles.modal} onClick={e => e.stopPropagation()}>
        {/* HEADER */}
        <div className={styles.header}>
          <div className={styles.title}>{cfg.titulo}</div>
          <span className={`${styles.badge} ${styles.badgeOT}`}>OT {orden.ot}</span>
          <span className={styles.badge}>
            <span
              className={styles.badgeEstadoDot}
              style={{ background: colorEstado(orden.estado) }}
            />
            {orden.estado}
          </span>
          <button
            type="button"
            className={styles.closeBtn}
            onClick={onClose}
            aria-label="Cerrar"
          >
            ✕
          </button>
        </div>

        {/* BODY */}
        <div className={styles.body}>
          {/* IZQUIERDA */}
          <div className={styles.left}>
            <div className={styles.section}>
              <div className={styles.sectionTitle}>Datos</div>
              <div className={styles.dataGrid}>
                <div className={styles.dataKey}>Rubro</div>
                <div className={styles.dataVal}>{orden.rubro || '—'}</div>
                <div className={styles.dataKey}>Responsable</div>
                <div className={styles.dataVal}>{orden.responsable || '—'}</div>
                <div className={styles.dataKey}>Fecha inicio</div>
                <div className={styles.dataVal}>{fechaCorta(orden.fecha_inicio_trabajos)}</div>
                <div className={styles.dataKey}>Fecha cierre</div>
                <div className={styles.dataVal}>{fechaCorta(orden.fecha_fin_trabajos)}</div>
                <div className={styles.dataKey}>Reincidente</div>
                <div className={styles.dataVal}>{orden.reincidencia ? 'Sí' : 'No'}</div>
              </div>
            </div>

            {muestraTextarea && (
              <div className={styles.section}>
                <label className={styles.label} htmlFor="obs-informe">
                  {cfg.labelTextarea}
                </label>
                <div className={styles.sublabel}>
                  Texto que aparecerá en el informe. Editá libremente.
                </div>
                {cargandoComentario ? (
                  <div className={styles.skeletonLineas} aria-busy="true">
                    <div className={styles.skeletonLinea} />
                    <div className={styles.skeletonLinea} />
                    <div className={styles.skeletonLinea} />
                  </div>
                ) : (
                  <>
                    <textarea
                      id="obs-informe"
                      className={styles.textarea}
                      value={observaciones}
                      onChange={e => {
                        const nuevoTexto = e.target.value.slice(0, MAX_OBSERVACIONES);
                        setObservaciones(nuevoTexto);

                        // Patch directo del DOM del iframe — sin reload
                        const doc = iframeRef.current?.contentDocument;
                        const el =
                          doc?.getElementById('antecedentes-texto') ??
                          doc?.getElementById('bloque-texto-naranja');
                        if (el) {
                          el.textContent =
                            nuevoTexto || 'Sin observaciones registradas.';
                          return;
                        }

                        // Fallback: iframe aún no cargado — regen completa
                        setHtmlPreview(construirHtml(nuevoTexto));
                      }}
                      rows={7}
                      maxLength={MAX_OBSERVACIONES}
                      placeholder={cfg.placeholderTextarea}
                    />
                    <div className={styles.contador}>
                      {observaciones.length}/{MAX_OBSERVACIONES} caracteres
                    </div>
                  </>
                )}
              </div>
            )}

            {necesitaFotos && (
              <div className={styles.section}>
                <div className={styles.sectionTitle}>Opciones</div>
                <label className={styles.checkboxRow}>
                  <input
                    type="checkbox"
                    checked={incluirFotos}
                    onChange={e => setIncluirFotos(e.target.checked)}
                  />
                  <span className={styles.checkboxText}>
                    <span className={styles.checkboxLabel}>Incluir fotos</span>
                    <span className={styles.sublabel}>
                      Renderizar las fotos disponibles en el informe
                    </span>
                  </span>
                </label>
              </div>
            )}

            <div className={styles.section}>
              <button
                type="button"
                className={styles.btnRefresh}
                onClick={handleActualizarAhora}
                disabled={cargandoComentario || generandoPreview}
              >
                Actualizar preview
              </button>
            </div>
          </div>

          {/* DERECHA */}
          <div className={styles.right}>
            {htmlPreview ? (
              <iframe
                key={`${orden.id}-${tipo}`}
                ref={iframeRef}
                className={styles.iframe}
                srcDoc={htmlPreview}
                title="preview-informe"
              />
            ) : !generandoPreview ? (
              <div className={styles.emptyState}>
                Hacé clic en <b>Actualizar preview</b>
              </div>
            ) : null}
            {generandoPreview && (
              <div className={styles.overlay}>
                <span className={styles.spinner} />
                <span>Actualizando preview...</span>
              </div>
            )}
          </div>
        </div>

        {/* FOOTER */}
        <div className={styles.footer}>
          <span className={styles.avisoImpresion}>
            Se abrirá el diálogo de impresión de Android. Para volver, usá el botón atrás.
          </span>
          <button type="button" className={styles.btnCancelar} onClick={onClose}>
            Cancelar
          </button>
          <button
            type="button"
            className={styles.btnSecondary}
            onClick={handleExportarHTML}
            disabled={!htmlPreview || generandoPreview}
          >
            Exportar HTML
          </button>
          <button
            type="button"
            className={styles.btnPrimary}
            onClick={handleExportarPDF}
            disabled={!htmlPreview || generandoPreview}
          >
            Exportar PDF →
          </button>
        </div>
      </div>
    </div>
  );
}

import { useRef, useEffect, useState } from 'react';
import type { ReactNode } from 'react';
import SignaturePad from 'signature_pad';
import CampoVideo from './CampoVideo';
import styles from './CampoRenderer.module.css';
import type { CampoDefinicion } from '../../services/camposService';

interface Props {
  campo:       CampoDefinicion;
  valor:       unknown;
  onChange:    (valor: unknown) => void;
  readonly?:   boolean;
  ordenId?:    string;
  proyectoId?: string;
}

export default function CampoRenderer({
  campo,
  valor,
  onChange,
  readonly    = false,
  ordenId     = '',
  proyectoId  = '',
}: Props) {
  const { tipo, nombre, obligatorio, opciones } = campo;

  const labelEl = (
    <label className={styles.label}>
      {nombre}
      {obligatorio && <span className={styles.requerido}>*</span>}
    </label>
  );

  if (readonly) {
    return (
      <div className={styles.campoWrap}>
        {labelEl}
        <div className={styles.valorReadonly}>
          {renderValorReadonly(tipo, valor, opciones)}
        </div>
      </div>
    );
  }

  return (
    <div className={styles.campoWrap}>
      {labelEl}
      {renderInput(tipo, valor, onChange, opciones, campo.id, ordenId, proyectoId)}
    </div>
  );
}

// ── Readonly display ────────────────────────────────────────────────────────

function renderValorReadonly(
  tipo: string,
  valor: unknown,
  _opciones: string[] | null
): ReactNode {
  if (valor === null || valor === undefined || valor === '') {
    return <span className={styles.vacio}>—</span>;
  }

  switch (tipo) {
    case 'booleano':
      return <span>{valor ? '✅ Sí' : '❌ No'}</span>;

    case 'fecha':
      try {
        return <span>{new Date(valor as string).toLocaleDateString('es-PY')}</span>;
      } catch {
        return <span>{String(valor)}</span>;
      }

    case 'fechahora':
      try {
        return (
          <span>
            {new Date(valor as string).toLocaleString('es-PY', {
              dateStyle: 'short',
              timeStyle: 'short',
            })}
          </span>
        );
      } catch {
        return <span>{String(valor)}</span>;
      }

    case 'hora':
      return <span>{String(valor)}</span>;

    case 'seleccion_multiple': {
      const arr = Array.isArray(valor) ? (valor as string[]) : [];
      if (arr.length === 0) return <span className={styles.vacio}>—</span>;
      return (
        <div className={styles.selMultipleBadges}>
          {arr.map(op => (
            <span key={op} className={styles.badge}>{op}</span>
          ))}
        </div>
      );
    }

    case 'firma':
      return (
        <img
          src={valor as string}
          alt="Firma"
          className={styles.firmaImagenReadonly}
        />
      );

    case 'video':
      return (
        <video
          src={valor as string}
          controls
          style={{ width: '100%', maxHeight: 160, borderRadius: 6 }}
        />
      );

    case 'url':
      return (
        <a href={valor as string} target="_blank" rel="noreferrer" className={styles.urlLink}>
          {String(valor)}
        </a>
      );

    default:
      return <span>{String(valor)}</span>;
  }
}

// ── Editable inputs ─────────────────────────────────────────────────────────

function renderInput(
  tipo:       string,
  valor:      unknown,
  onChange:   (v: unknown) => void,
  opciones:   string[] | null,
  campoId:    string,
  ordenId:    string,
  proyectoId: string,
): ReactNode { 
  switch (tipo) {

    case 'texto':
      return (
        <input
          className={styles.input}
          type="text"
          value={(valor as string) ?? ''}
          onChange={e => onChange(e.target.value)}
          maxLength={500}
        />
      );

    case 'numero':
    case 'decimal':
      return (
        <input
          className={styles.input}
          type="number"
          step={tipo === 'decimal' ? '0.01' : '1'}
          value={(valor as string) ?? ''}
          onChange={e => onChange(e.target.value === '' ? null : Number(e.target.value))}
        />
      );

    case 'fecha':
      return (
        <input
          className={styles.input}
          type="date"
          value={(valor as string) ?? ''}
          onChange={e => onChange(e.target.value)}
        />
      );

    case 'fechahora':
      return (
        <input
          className={styles.input}
          type="datetime-local"
          value={(valor as string) ?? ''}
          onChange={e => onChange(e.target.value)}
        />
      );

    case 'hora':
      return (
        <input
          className={styles.input}
          type="time"
          value={(valor as string) ?? ''}
          onChange={e => onChange(e.target.value)}
        />
      );

    case 'seleccion_unica':
      return (
        <select
          className={styles.select}
          value={(valor as string) ?? ''}
          onChange={e => onChange(e.target.value)}
        >
          <option value="">— Seleccionar —</option>
          {(opciones ?? []).map(op => (
            <option key={op} value={op}>{op}</option>
          ))}
        </select>
      );

    case 'seleccion_multiple':
      return (
        <CampoSeleccionMultiple
          valor={valor}
          onChange={onChange}
          opciones={opciones}
        />
      );

    case 'booleano':
      return (
        <label className={styles.checkboxLabel}>
          <input
            type="checkbox"
            checked={Boolean(valor)}
            onChange={e => onChange(e.target.checked)}
          />
          <span>{Boolean(valor) ? 'Sí' : 'No'}</span>
        </label>
      );

    case 'url':
      return (
        <input
          className={styles.input}
          type="url"
          value={(valor as string) ?? ''}
          onChange={e => onChange(e.target.value)}
          placeholder="https://"
        />
      );

    case 'firma':
      return (
        <CampoFirma valor={valor} onChange={onChange} />
      );

    case 'video':
      return (
        <CampoVideo
          valor={valor}
          onChange={onChange}
          ordenId={ordenId}
          proyectoId={proyectoId}
          campoId={campoId}
        />
      );

    default:
      return <span className={styles.vacio}>Tipo no soportado: {tipo}</span>;
  }
}

// ── Sub-componente: Selección múltiple ──────────────────────────────────────

interface SelMultipleProps {
  valor:    unknown;
  onChange: (v: unknown) => void;
  opciones: string[] | null;
}

function CampoSeleccionMultiple({ valor, onChange, opciones }: SelMultipleProps) {
  const seleccionados: string[] = Array.isArray(valor) ? (valor as string[]) : [];

  const toggle = (op: string) => {
    if (seleccionados.includes(op)) {
      onChange(seleccionados.filter(s => s !== op));
    } else {
      onChange([...seleccionados, op]);
    }
  };

  if (!opciones || opciones.length === 0) {
    return <span className={styles.vacio}>Sin opciones definidas</span>;
  }

  return (
    <div className={styles.selMultipleWrap}>
      {opciones.map(op => (
        <label key={op} className={styles.selMultipleItem}>
          <input
            type="checkbox"
            checked={seleccionados.includes(op)}
            onChange={() => toggle(op)}
          />
          <span>{op}</span>
        </label>
      ))}
    </div>
  );
}

// ── Sub-componente: Firma digital ───────────────────────────────────────────

interface FirmaProps {
  valor:    unknown;
  onChange: (v: unknown) => void;
}

function CampoFirma({ valor, onChange }: FirmaProps) {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const padRef    = useRef<SignaturePad | null>(null);

  const [modo, setModo] = useState<'ver' | 'dibujar'>(
    valor && typeof valor === 'string' ? 'ver' : 'dibujar'
  );

  useEffect(() => {
    if (modo !== 'dibujar' || !canvasRef.current) return;

    const pad = new SignaturePad(canvasRef.current, {
      backgroundColor: 'rgb(255, 255, 255)',
      penColor: 'rgb(0, 0, 0)',
      minWidth: 1,
      maxWidth: 3,
    });
    padRef.current = pad;

    const canvas = canvasRef.current;
    const ratio  = Math.max(window.devicePixelRatio || 1, 1);
    canvas.width  = canvas.offsetWidth  * ratio;
    canvas.height = canvas.offsetHeight * ratio;
    const ctx = canvas.getContext('2d');
    if (ctx) ctx.scale(ratio, ratio);
    pad.clear();

    return () => { pad.off(); };
  }, [modo]);

  const handleGuardar  = () => {
    if (!padRef.current || padRef.current.isEmpty()) return;
    onChange(padRef.current.toDataURL('image/png'));
    setModo('ver');
  };
  const handleLimpiar  = () => { padRef.current?.clear(); };
  const handleEliminar = () => { onChange(null); setModo('dibujar'); };

  if (modo === 'ver' && valor && typeof valor === 'string') {
    return (
      <div className={styles.firmaWrap}>
        <img src={valor} alt="Firma guardada" className={styles.firmaImagen} />
        <div className={styles.firmaBtns}>
          <button type="button" className={styles.firmaBtn} onClick={() => setModo('dibujar')}>
            ✏️ Redibujar
          </button>
          <button
            type="button"
            className={`${styles.firmaBtn} ${styles.firmaBtnEliminar}`}
            onClick={handleEliminar}
          >
            🗑 Eliminar
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className={styles.firmaWrap}>
      <canvas ref={canvasRef} className={styles.firmaCanvas} />
      <div className={styles.firmaBtns}>
        <button type="button" className={styles.firmaBtn} onClick={handleLimpiar}>
          Limpiar
        </button>
        <button
          type="button"
          className={`${styles.firmaBtn} ${styles.firmaBtnGuardar}`}
          onClick={handleGuardar}
        >
          ✔ Guardar firma
        </button>
        {typeof valor === 'string' && valor !== '' && (
          <button type="button" className={styles.firmaBtn} onClick={() => setModo('ver')}>
            Cancelar
          </button>
        )}
      </div>
      <p className={styles.firmaHint}>Dibuje con dedo, stylus o ratón</p>
    </div>
  );
}

/**
 * CampoVideo.tsx — Campo personalizado tipo video
 * Flujo: selección → validación duración → compresión FFmpeg → upload Storage → URL en JSONB
 * Límites: 30s duración, 50MB post-compresión, 1 video por campo
 */

import { useRef, useState } from 'react';
import { supabase } from '../../db/supabase';
import styles from './CampoVideo.module.css';

const MAX_DURACION_SEG = 30;
const MAX_TAMANO_MB    = 50;

// URLs del core no-threaded (no requiere SharedArrayBuffer ni headers COOP/COEP)
const FFMPEG_CORE_URL = 'https://unpkg.com/@ffmpeg/core@0.12.6/dist/esm/ffmpeg-core.js';
const FFMPEG_WASM_URL = 'https://unpkg.com/@ffmpeg/core@0.12.6/dist/esm/ffmpeg-core.wasm';

type Estado = 'vacio' | 'validando' | 'comprimiendo' | 'subiendo' | 'listo' | 'error';

interface Props {
  valor:      unknown;
  onChange:   (v: unknown) => void;
  ordenId:    string;
  proyectoId: string;
  campoId:    string;
}

export default function CampoVideo({
  valor,
  onChange,
  ordenId,
  proyectoId: _proyectoId,
  campoId,
}: Props) {
  const inputRef = useRef<HTMLInputElement>(null);
  const [estado,   setEstado]   = useState<Estado>(valor ? 'listo' : 'vacio');
  const [progreso, setProgreso] = useState(0);
  const [error,    setError]    = useState<string | null>(null);
  const [metaDur,  setMetaDur]  = useState<number | null>(null);
  const [metaMB,   setMetaMB]   = useState<number | null>(null);

  const videoUrl = typeof valor === 'string' && valor.length > 0 ? valor : null;

  // ── Obtener duración sin FFmpeg ───────────────────────────────────────────
  function getDuracion(file: File): Promise<number> {
    return new Promise((resolve, reject) => {
      const vid = document.createElement('video');
      vid.preload = 'metadata';
      const url = URL.createObjectURL(file);
      vid.onloadedmetadata = () => { URL.revokeObjectURL(url); resolve(vid.duration); };
      vid.onerror          = () => { URL.revokeObjectURL(url); reject(new Error('No se pudo leer el video')); };
      vid.src = url;
    });
  }

  // ── Compresión FFmpeg (lazy load del WASM ~31 MB) ─────────────────────────
  async function comprimir(
    file: File,
    onProgress: (p: number) => void
  ): Promise<File> {
    try {
      const { FFmpeg }     = await import('@ffmpeg/ffmpeg');
      const { fetchFile, toBlobURL } = await import('@ffmpeg/util');

      const ff = new FFmpeg();
      ff.on('progress', ({ progress }) => onProgress(Math.round(progress * 100)));

      await ff.load({
        coreURL: await toBlobURL(FFMPEG_CORE_URL, 'text/javascript'),
        wasmURL: await toBlobURL(FFMPEG_WASM_URL, 'application/wasm'),
      });

      const ext    = file.name.split('.').pop() ?? 'mp4';
      const inName = `in.${ext}`;
      const outName = 'out.mp4';

      await ff.writeFile(inName, await fetchFile(file));

      // 720p H.264 · audio AAC 128k · faststart para streaming
      await ff.exec([
        '-i', inName,
        '-vf', 'scale=-2:min(720\\,ih)',   // no upscale si ya es menor a 720p
        '-c:v', 'libx264',
        '-preset', 'fast',
        '-crf', '28',
        '-c:a', 'aac',
        '-b:a', '128k',
        '-movflags', '+faststart',
        outName,
      ]);

      const data = (await ff.readFile(outName)) as unknown as Uint8Array<ArrayBuffer>;
      return new File([new Blob([data], { type: 'video/mp4' })], outName, { type: 'video/mp4' });

    } catch (err) {
      // FFmpeg no disponible (offline, CDN caído) → subir sin comprimir con advertencia
      console.warn('[CampoVideo] FFmpeg no disponible, subiendo sin comprimir:', err);
      return file;
    }
  }

  // ── Upload a Storage (bucket fotos, carpeta VIDEO/) ───────────────────────
  async function subirAStorage(file: File): Promise<string> {
    const ts   = Date.now();
    const path = `${ordenId}/VIDEO/${campoId}_${ts}.mp4`;

    const { error } = await supabase.storage
      .from('fotos')
      .upload(path, file, { cacheControl: '3600', upsert: false });

    if (error) throw new Error(`Error al subir video: ${error.message}`);

    const { data } = supabase.storage.from('fotos').getPublicUrl(path);
    return data.publicUrl;
  }

  // ── Handler principal ─────────────────────────────────────────────────────
  async function handleSeleccionar(e: React.ChangeEvent<HTMLInputElement>) {
    const file = e.target.files?.[0];
    if (!file) return;

    setError(null);

    if (!file.type.startsWith('video/')) {
      setError('El archivo debe ser un video (MP4, MOV, WebM)');
      return;
    }

    try {
      // 1. Validar duración
      setEstado('validando');
      const dur = await getDuracion(file);
      setMetaDur(dur);

      if (dur > MAX_DURACION_SEG) {
        setError(`El video dura ${Math.round(dur)}s. Máximo: ${MAX_DURACION_SEG}s`);
        setEstado('error');
        return;
      }

      // 2. Comprimir
      setEstado('comprimiendo');
      setProgreso(0);
      const comprimido = await comprimir(file, setProgreso);
      setProgreso(100);

      // 3. Validar tamaño post-compresión
      const mb = comprimido.size / (1024 * 1024);
      setMetaMB(mb);

      if (mb > MAX_TAMANO_MB) {
        setError(`El video pesa ${mb.toFixed(1)} MB tras comprimir. Máximo: ${MAX_TAMANO_MB} MB`);
        setEstado('error');
        return;
      }

      // 4. Subir
      setEstado('subiendo');
      const url = await subirAStorage(comprimido);

      onChange(url);
      setEstado('listo');

    } catch (err) {
      setError(err instanceof Error ? err.message : 'Error desconocido');
      setEstado('error');
    }

    // Reset input para permitir reselección del mismo archivo
    if (inputRef.current) inputRef.current.value = '';
  }

  function handleEliminar() {
    // Nota: el archivo en Storage queda huérfano hasta limpieza futura.
    // Para borrado real necesitamos el path (no solo la URL) — pendiente S14+.
    onChange(null);
    setEstado('vacio');
    setMetaDur(null);
    setMetaMB(null);
  }

  // ── Render: video cargado ─────────────────────────────────────────────────
  if (estado === 'listo' && videoUrl) {
    return (
      <div className={styles.wrap}>
        <video src={videoUrl} controls className={styles.player} />
        {(metaDur !== null || metaMB !== null) && (
          <div className={styles.meta}>
            {metaDur !== null && <span>⏱ {Math.round(metaDur)}s</span>}
            {metaMB  !== null && <span>📦 {metaMB.toFixed(1)} MB</span>}
            <span>MP4 · 720p</span>
          </div>
        )}
        <button
          type="button"
          className={styles.btnEliminar}
          onClick={handleEliminar}
        >
          🗑 Eliminar video
        </button>
      </div>
    );
  }

  // ── Render: en progreso ───────────────────────────────────────────────────
  if (estado === 'validando') {
    return (
      <div className={styles.wrap}>
        <p className={styles.estadoTexto}>🔍 Verificando duración…</p>
      </div>
    );
  }

  if (estado === 'comprimiendo') {
    return (
      <div className={styles.wrap}>
        <p className={styles.estadoTexto}>⚙️ Comprimiendo a 720p… {progreso}%</p>
        <div className={styles.progressTrack}>
          <div className={styles.progressBar} style={{ width: `${progreso}%` }} />
        </div>
        {progreso === 0 && (
          <p className={styles.hint}>Cargando compresor (~30 MB), un momento…</p>
        )}
      </div>
    );
  }

  if (estado === 'subiendo') {
    return (
      <div className={styles.wrap}>
        <p className={styles.estadoTexto}>☁️ Subiendo video…</p>
        <div className={styles.progressTrack}>
          <div className={styles.progressBar} style={{ width: '100%', opacity: 0.6 }} />
        </div>
      </div>
    );
  }

  // ── Render: vacío / error ─────────────────────────────────────────────────
  return (
    <div className={styles.wrap}>
      <input
        ref={inputRef}
        type="file"
        accept="video/*"
        onChange={handleSeleccionar}
        style={{ display: 'none' }}
      />
      <button
        type="button"
        className={styles.btnSeleccionar}
        onClick={() => { setError(null); setEstado('vacio'); inputRef.current?.click(); }}
      >
        📹 Seleccionar video
      </button>
      <p className={styles.hint}>
        Máx. {MAX_DURACION_SEG}s · {MAX_TAMANO_MB} MB · MP4 / MOV / WebM
      </p>
      {error && (
        <p className={styles.error}>{error}</p>
      )}
    </div>
  );
}

