                onChange={e => setInvRol(e.target.value as RolMiembro)}
                style={{
                  width: '100%', height: 40, padding: '0 12px',
                  border: '2px solid #001E40', borderRadius: 8, fontSize: 13,
                  background: 'white', cursor: 'pointer', outline: 'none',
                  fontFamily: 'inherit',
