                  fontFamily: 'inherit',
                }}
              >{enviandoInv ? '⏳ Enviando...' : '✉️ Enviar Invitación'}</button>
            </div>
          </div>
        </div>
      )}

      {ToastComponent}
    </div>
  );
}

