    @page {
      size: A4 portrait;
      margin: 28mm 15mm 22mm 15mm;
    }
    @media print {
      .no-print { display: none !important; }
      body { background: white !important; }
      .page-break { page-break-before: always; }
      img { max-height: 160px; object-fit: cover; }

      /* Encabezado repetido en cada página */
